function configure(input){
  const c={...input,run_id:new Date().toISOString()};
  if(!/^[\w-]{20,}$/.test(c.spreadsheet_id||'')||/REPLACE/.test(c.spreadsheet_id))throw new Error('Set spreadsheet_id and create Queries and Results with the canvas headers.');
  c.own_domain=host('https://'+clean(c.own_domain));c.brand_aliases=lines(c.brand_aliases);c.excluded_domains=lines(c.excluded_domains).map(d=>host('https://'+d));
  if(!c.own_domain||!c.brand_aliases.length||c.brand_aliases.length>10||c.brand_aliases.some(a=>a.length<3||a.length>80)||c.excluded_domains.some(d=>!d))throw new Error('Set a bare brand domain, 1-10 aliases of 3-80 characters and valid excluded domains.');
  for(const k of ['max_items','max_pages']){c[k]=Number(c[k]);if(!Number.isInteger(c[k])||c[k]<1||c[k]>10)throw new Error(k+' must be between 1 and 10');}
  c.gl=clean(c.gl).toLowerCase();c.hl=clean(c.hl).toLowerCase();
  if(!/^[a-z]{2}$/.test(c.gl)||!/^[a-z]{2}$/.test(c.hl))throw new Error('gl and hl must be two-letter codes.');
  c.content_selector=clean(c.content_selector)||'main, article, [role="main"]';
  if(typeof c.js_rendering!=='boolean')throw new Error('js_rendering must be true or false.');return c;
}

function host(v) { return url(v)?.split('/')[2] || ''; }

function lines(v) { return [...new Set(String(v || '').split('\n').map(clean).filter(Boolean))]; }

function url(v) {
  const m = /^https?:\/\/([a-z0-9.-]+)(?::(443|80))?(\/[^\s#]*)?(?:#.*)?$/i.exec(clean(v));
  if (!m || !m[1].includes('.') || /^[\d.]+$/.test(m[1]) || /(^|\.)(localhost|local|internal|invalid|test)$/.test(m[1])) return '';
  const [path, query] = (m[3] || '/').split('?');
  const params = (query || '').split('&').filter(p => p && !/^(utm_[^=]*|gclid|fbclid)=/i.test(p)).sort();
  return 'https://' + m[1].toLowerCase().replace(/^www\./, '') + (path === '/' ? '/' : path.replace(/\/$/, '')) + (params.length ? '?' + params.join('&') : '');
}

function clean(v) { return typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : ''; }

return [{json:configure($input.first().json)}];

function planQueries(c,rows){
  const queries=rows.map(r=>clean(r.query)).filter(Boolean);
  if(!queries.length||queries.length>c.max_items||queries.some(q=>q.length>250))throw new Error('Use 1-max_items query rows, up to 250 characters each.');
  if(new Set(queries.map(q=>q.normalize('NFKC').toLowerCase())).size!==queries.length)throw new Error('Duplicate query rows.');
  return queries.map(query=>({query,fields:{gl:c.gl,hl:c.hl}}));
}

function clean(v) { return typeof v === 'string' ? v.replace(/\s+/g, ' ').trim() : ''; }

return planQueries($('Validate settings').first().json,$input.all().map(x=>x.json)).map(json=>({json}));

function attachNews(p,r){
  const observed=!r.error&&r.requestMetadata?.status==='ok'&&Array.isArray(r.newsResults);
  const results=[];let rejected=0;
  if(observed)for(const n of r.newsResults.slice(0,100)){
    const entries=Array.isArray(n.stories)?n.stories:[n];
    for(const article of entries){const canonical=url(article.link);if(!canonical){rejected++;continue;}results.push({url:canonical,source_url:article.link,title:clean(article.title),publisher:clean(article.source?.name||article.source),published_at:clean(article.date)});}
  }
  return {...p,status:observed?'observed':'news_unavailable',results,rejected,results_limited:observed&&r.newsResults.length>100,metadata:metadata(r)};
}

