function metadata(r) { const m = r?.requestMetadata || {}; return { id: clean(m.id), status: clean(m.status), html: clean(m.html), json: clean(m.json), search_url: clean(m.url) }; }

function pair(plans,items){
  const seen=new Set();const pairs=items.map(item=>{const refs=Array.isArray(item.pairedItem)?item.pairedItem:[item.pairedItem];if(refs.length!==1)throw new Error('Ambiguous response pairing.');const i=refs[0]?.item;if(!Number.isInteger(i)||!plans[i]||seen.has(i))throw new Error('Missing or duplicate response pairing.');seen.add(i);return{plan:plans[i].json,response:item.json};});
  if(seen.size!==plans.length)throw new Error('Missing response items.');return pairs;
}

