  const m = /^https?:\/\/([a-z0-9.-]+)(?::(443|80))?(\/[^\s#]*)?(?:#.*)?$/i.exec(clean(v));
  if (!m || !m[1].includes('.') || /^[\d.]+$/.test(m[1]) || /(^|\.)(localhost|local|internal|invalid|test)$/.test(m[1])) return '';
  const [path, query] = (m[3] || '/').split('?');
  const params = (query || '').split('&').filter(p => p && !/^(utm_[^=]*|gclid|fbclid)=/i.test(p)).sort();
  return 'https://' + m[1].toLowerCase().replace(/^www\./, '') + (path === '/' ? '/' : path.replace(/\/$/, '')) + (params.length ? '?' + params.join('&') : '');
}

return pair($('Check saved keys').all(),$input.all()).map(({plan,response})=>({json:attachNews(plan,response)}));

function sourcePlan(c,searches){
  const byUrl=new Map();for(const s of searches)for(const a of s.results){let source=byUrl.get(a.url);if(!source){source={...a,queries:[],request_ids:[]};byUrl.set(a.url,source);}if(!source.queries.includes(s.query))source.queries.push(s.query);if(s.metadata.id&&!source.request_ids.includes(s.metadata.id))source.request_ids.push(s.metadata.id);}
  const sources=[...byUrl.values()].sort((a,b)=>b.queries.length-a.queries.length||b.published_at.localeCompare(a.published_at)||a.url.localeCompare(b.url));let selected=0;
  return sources.map(s=>({...s,status:[c.own_domain,...c.excluded_domains].some(d=>domainMatches(host(s.url),d))?'excluded_domain':selected++<c.max_pages?'fetch':'page_budget_exceeded'}));
}

