function readEvidence(p,r,x){
  const text=clean(x.text),links=Array.isArray(x.links)?x.links.filter(v=>typeof v==='string'):[];
  const ok=!r.error&&r.requestMetadata?.status==='ok'&&(!r.statusCode||(r.statusCode>=200&&r.statusCode<300))&&!x.error&&text.length>=150;
  return {...p,page_status:ok?'read':'unknown',reason:ok?'':r.error?'Page request failed.':x.error?'HTML extraction failed.':r.statusCode&&(r.statusCode<200||r.statusCode>=300)?'Source HTTP '+r.statusCode:'No usable article text. Check the selector and rendering setting.',text:ok?text.slice(0,30000):'',truncated:text.length>30000,links:links.slice(0,500),links_truncated:links.length>500,title:clean(x.title),metadata:metadata(r)};
}

