const pages=pair($('Pair source pages').all(),$input.all()).map(({plan,response})=>readEvidence(plan.plan,plan.response,response));return [{json:{pages}}];

function reviewRows(c,sources,pages,searches){
  const rows=searches.map(s=>outputRow(c,'news_query',s.query,s.query,s.status==='news_unavailable'?'news_unavailable':s.results.length?'news_inventory':'no_returned_articles',{search:s,limits:'One returned Google News response, not a complete media inventory or proof of no coverage.'}));
  for(const source of sources){
    const p=pages.find(p=>p.url===source.url);const read=p?.page_status==='read';const brand=read?mentions(p.text,c.brand_aliases):[],links=read?ownLinks(c,p):[];
    const status=source.status!=='fetch'?source.status:!read?'page_unavailable':links.length?'brand_link_observed':!brand.length?'no_brand_match_in_text':p.truncated||p.links_truncated?'incomplete_page_review':'review_unlinked_mention';
    rows.push(outputRow(c,'news_source',source.url,source.title,status,{source,page_title:p?.title||'',page_status:p?.page_status||'not_fetched',page_reason:p?.reason||'',page_metadata:p?.metadata||{},brand_mentions:brand,own_links:[...new Set(links)],text_truncated:!!p?.truncated,links_truncated:!!p?.links_truncated,limits:'A candidate means a brand match and no direct brand-domain link in the inspected response. Check the full article, redirects, ownership and relevance before outreach. No messages or listing changes are made.'}));
  }
  return rows;
}

