function mentions(text, names) {
  return names.flatMap(name => {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = new RegExp('(?:^|[^\\p{L}\\p{N}])(' + escaped + ')(?=$|[^\\p{L}\\p{N}])', 'iu').exec(text);
    return m ? [{ name, excerpt: text.slice(Math.max(0, m.index - 100), m.index + name.length + 180) }] : [];
  });
}

function metadata(r) { const m = r?.requestMetadata || {}; return { id: clean(m.id), status: clean(m.status), html: clean(m.html), json: clean(m.json), search_url: clean(m.url) }; }

function outputRow(c,kind,id,topic,status,e){
  const evidence_json=JSON.stringify(e);if(evidence_json.length>44000)throw new Error('Evidence exceeds the Sheets cell limit. Reduce the batch.');
  return {result_key:JSON.stringify([kind,c.own_domain,c.brand_aliases,c.gl,c.hl,id]),checked_at:c.run_id,topic,status,title:e.source?.title||e.page_title||'',source_url:e.source?.source_url||'',publisher:e.source?.publisher||'',published_at:e.source?.published_at||'',brand_excerpt:(e.brand_mentions||[]).map(m=>m.excerpt).join('\n'),observed_links:(e.own_links||[]).join('\n'),citing_queries:(e.source?.queries||[topic]).join('\n'),evidence_json};
}

function ownLinks(c,p){
  return p.links.filter(link=>{const u=url(link.startsWith('//')?'https:'+link:link);return u&&domainMatches(host(u),c.own_domain);}).map(link=>url(link.startsWith('//')?'https:'+link:link));
}

function domainMatches(a, b) { return !!a && !!b && (a === b || a.endsWith('.' + b)); }

function host(v) { return url(v)?.split('/')[2] || ''; }

